'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Slider, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './slider.css'

import { LockGlyph } from './glyphs'

/**
 * Slider: the prediction slider.
 *
 * A player drags to a number and then commits it. Those are two acts, not one
 * (BDS-014, REQ-026): moving the thumb is thinking out loud, pressing the
 * commit control is answering. A slider that answered on release would settle
 * every prediction at whatever number the thumb happened to be under when the
 * finger left the glass, which is the wrong answer more often than it is the
 * right one.
 *
 * So a moved but uncommitted slider is `data-gs-selected`, exactly as a picked
 * option is: picked, reversible. `data-gs-committed` is locked in. There is no
 * third "pending" state, because there is no third thing to be.
 *
 * It snaps. The value only ever lands on a multiple of `increment` from `min`,
 * five by default, because a prediction of 47 and a prediction of 48 are the
 * same prediction and a host that has to bucket them afterwards is doing the
 * component's job.
 *
 * It performs nothing. It does not know whether the prediction is right, score
 * it, or send it anywhere. The host takes `onCommitted` and settles.
 */

export type SliderCommits = 'separate' | 'immediate'

export interface SliderProps
  extends Omit<
    React.HTMLAttributes<HTMLDivElement>,
    'children' | 'onChange' | 'defaultValue' | 'role'
  > {
  /** The name of the thing being predicted. A slider with no name is unusable. */
  label: string
  /** The floor. */
  min?: number
  /** The ceiling. */
  max?: number
  /** The interval the value snaps to. Five, per BDS-014, unless a host says otherwise. */
  increment?: number
  /** The starting value, for an uncontrolled slider. Snapped like any other. */
  defaultValue?: number
  /** The value, when the host owns it. Snapped like any other. */
  value?: number
  /**
   * Whether committing is its own act. `separate` renders a commit control and
   * moving the thumb answers nothing. `immediate` is for the rare surface where
   * the drag *is* the answer, a volume or a brightness rather than a prediction.
   */
  commits?: SliderCommits
  /** The word on the commit control. */
  commitLabel?: string
  /** Render the value as something other than the bare number, e.g. `45%`. */
  format?: (value: number) => string
  /** Not available at all. Goes flat, takes no focus. */
  disabled?: boolean
  /**
   * Available later, not now. Keeps its shape, shows a padlock, stays
   * focusable. Ignored when `disabled` is also set, for the reason `button`
   * gives: a control cannot be flat and keep its shape at once.
   */
  locked?: boolean
  /** Fired for every snapped value the player lands on, drag or keyboard. */
  onValueChange?: (value: number) => void
  /** Fired once, when the player answers. */
  onCommitted?: (value: number) => void
}

/**
 * The words that go with the states. Taken from `choice`, deliberately: a
 * picked option and a moved slider are the same state, and two vocabularies for
 * one state is how a screen reader user learns the library is two libraries.
 */
const STATE_LABEL = {
  selected: 'selected',
  committed: 'locked in',
  locked: 'locked',
} as const

// The glyph, because a state that is only a colour is not a state, is
// `LockGlyph` from `@gamestage/glyphs`. It was a colour emoji, which ignored
// every colour token and changed silhouette per operating system (GSUI-103).
// The character is not repeated here: the gate greps the source for emoji, and
// a mention would read as a use.

/** Land on the grid, then on the range. Never outside either. */
function snapTo(raw: number, min: number, max: number, increment: number): number {
  const step = increment > 0 ? increment : 1
  const clamped = Math.min(max, Math.max(min, raw))
  const snapped = min + Math.round((clamped - min) / step) * step
  // A fractional increment accumulates float error over a drag, and 44.99999
  // renders as 44.99999. Five places is past anything a prediction needs.
  const tidy = Number(snapped.toFixed(5))
  return Math.min(max, Math.max(min, tidy))
}

export function Slider({
  label,
  min = 0,
  max = 100,
  increment = 5,
  defaultValue,
  value,
  commits = 'separate',
  commitLabel = 'Lock it in',
  format,
  disabled = false,
  locked = false,
  onValueChange,
  onCommitted,
  className,
  ...rest
}: SliderProps) {
  const isLocked = locked && !disabled

  const [internal, setInternal] = React.useState(() =>
    snapTo(defaultValue ?? min, min, max, increment),
  )
  const [moved, setMoved] = React.useState(false)
  const [committed, setCommitted] = React.useState(false)
  const dragging = React.useRef(false)

  const controlled = value !== undefined
  const current = snapTo(controlled ? value : internal, min, max, increment)

  // Committed is the end of the road: the answer is in, and the contract says
  // it is no longer reversible. Disabled and locked are the host's two ways of
  // saying "not now", which `button` already separates.
  const frozen = disabled || isLocked || committed

  const state = committed ? 'committed' : moved ? 'selected' : undefined

  const rendered = format ? format(current) : String(current)

  // The name carries the state, because a screen reader user gets no fill, no
  // thumb travel and no glyph. The number is not in here: `aria-valuenow` and
  // `aria-valuetext` carry it, and putting it in the name as well makes every
  // arrow key read the value twice.
  const words = [label]
  if (state) words.push(STATE_LABEL[state])
  if (isLocked) words.push(STATE_LABEL.locked)

  function change(next: number) {
    if (frozen || next === current) return
    if (!controlled) setInternal(next)
    setMoved(true)
    onValueChange?.(next)
    // `immediate` means the move is the answer. It still passes through the
    // same snap, so an immediate slider cannot report a value a separate one
    // could not.
    if (commits === 'immediate') {
      setCommitted(true)
      onCommitted?.(next)
    }
  }

  function commit() {
    if (frozen || !moved) return
    setCommitted(true)
    onCommitted?.(current)
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (frozen) return
    const step = increment > 0 ? increment : 1
    let next: number | undefined
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowUp':
        next = current + step
        break
      case 'ArrowLeft':
      case 'ArrowDown':
        next = current - step
        break
      case 'Home':
        next = min
        break
      case 'End':
        next = max
        break
      default:
        return
    }
    // The page scrolls on arrow keys and jumps to the top on Home, and a player
    // holding an arrow to reach 80 would lose the slider off the bottom of the
    // screen.
    event.preventDefault()
    change(snapTo(next, min, max, increment))
  }

  function valueFromPointer(
    event: React.PointerEvent<HTMLDivElement>,
  ): number | undefined {
    const rect = event.currentTarget.getBoundingClientRect()
    // A zero-width track means the element is not laid out yet. Dividing by it
    // yields Infinity, which snaps to max, so the first pointer event on an
    // unlaid-out slider would answer the maximum.
    if (rect.width === 0) return undefined
    const fraction = (event.clientX - rect.left) / rect.width
    return snapTo(min + fraction * (max - min), min, max, increment)
  }

  function onPointerDown(event: React.PointerEvent<HTMLDivElement>) {
    if (frozen) return
    dragging.current = true
    const next = valueFromPointer(event)
    if (next !== undefined) change(next)
  }

  function onPointerMove(event: React.PointerEvent<HTMLDivElement>) {
    if (frozen || !dragging.current) return
    const next = valueFromPointer(event)
    if (next !== undefined) change(next)
  }

  function endDrag() {
    dragging.current = false
  }

  // Unitless, 0 to 1, so the stylesheet can write `(100% - thumb) * ratio` and
  // the thumb stays inside the bar at both ends. A percentage could not: CSS
  // cannot divide one by another.
  const span = max - min
  const ratio = span > 0 ? (current - min) / span : 0

  return (
    <div
      {...rest}
      className={['gs-slider', className].filter(Boolean).join(' ')}
      data-gs-component="slider"
      data-gs-value={current}
      data-gs-min={min}
      data-gs-max={max}
      data-gs-increment={increment}
      data-gs-commits={commits}
      data-gs-selected={state === 'selected' ? 'true' : undefined}
      data-gs-committed={state === 'committed' ? 'true' : undefined}
      data-gs-disabled={disabled ? 'true' : undefined}
      data-gs-locked={isLocked ? 'true' : undefined}
    >
      <span className="gs-slider__label" data-gs-scope="slider" data-gs-part="label" aria-hidden="true">
        {label}
      </span>
      <span className="gs-slider__value gs-display-type" data-gs-scope="slider" data-gs-part="value" aria-hidden="true">
        {rendered}
      </span>

      {/* The widget, and only the widget. `role="slider"` takes no interactive
          children, so the commit control is a sibling below rather than a child
          of this element. */}
      <div
        className="gs-slider__track"
        data-gs-scope="slider" data-gs-part="track"
        // The track is an input, so it is inset; the thumb is a control, so it
        // is raised. BDS-040's whole rule, in one component, made assertable.
        data-gs-elevation="inset"
        role="slider"
        tabIndex={disabled ? -1 : 0}
        aria-label={words.join(', ')}
        aria-valuenow={current}
        aria-valuemin={min}
        aria-valuemax={max}
        aria-valuetext={format ? rendered : undefined}
        // Horizontal only. A vertical prediction slider would need an attribute
        // to be found by and the contract allocates none, so it is not offered
        // rather than offered unassertably.
        aria-orientation="horizontal"
        aria-disabled={frozen || undefined}
        // The fill width is data, not design: it is the only number in this
        // component a stylesheet cannot derive, so it arrives as a custom
        // property and the CSS keeps every colour and size in tokens.
        style={{ '--gs-slider-ratio': ratio } as React.CSSProperties}
        onKeyDown={onKeyDown}
        onPointerDown={onPointerDown}
        onPointerMove={onPointerMove}
        onPointerUp={endDrag}
        onPointerCancel={endDrag}
        onLostPointerCapture={endDrag}
      >
        <span className="gs-slider__fill" data-gs-scope="slider" data-gs-part="fill" data-gs-animates="motion" />
        <span
          className="gs-slider__thumb"
          data-gs-scope="slider" data-gs-part="thumb"
          data-gs-elevation="raised"
          // The thumb travels and does nothing else, so it is motion and stops
          // dead under reduced motion. The fill's colour and the committed
          // treatment are emphasis and survive, which is how a player who
          // cannot see it move still sees where it got to.
          data-gs-animates="motion"
        />
      </div>

      {isLocked ? (
        <span
          className="gs-slider__glyph"
          data-gs-scope="slider" data-gs-part="glyph"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          <LockGlyph />
        </span>
      ) : null}

      {commits === 'separate' && !frozen && moved ? (
        <button
          type="button"
          className="gs-slider__commit gs-action-type gs-pressable"
          data-gs-scope="slider" data-gs-part="commit"
          data-gs-animates="motion"
          onClick={commit}
        >
          {commitLabel}
        </button>
      ) : null}
    </div>
  )
}

/* Slider. Every value comes from a token; nothing here is a literal colour. */

.gs-slider {
  display: grid;
  grid-template-areas: 'label glyph' 'value value' 'track track' 'commit commit';
  grid-template-columns: 1fr auto;
  align-items: center;
  gap: var(--gs-space-2);
  width: 100%;
}

.gs-slider__label {
  grid-area: label;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: uppercase;
  color: var(--gs-color-ink-secondary);
}

/* Tabular numerals, or the readout shifts under the thumb on every snap and the
   number reads as jittering rather than changing. */
.gs-slider__value {
  grid-area: value;
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  color: var(--gs-color-ink);
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* -- the track: inset, because it is an input (BDS-040) -------------------- */
.gs-slider__track {
  grid-area: track;
  position: relative;
  box-sizing: border-box;
  display: block;
  width: 100%;

  /* The track is the touch target, not the thumb: a 12px bar is not a thing a
     thumb hits. The bar is drawn inside it. */
  min-height: var(--gs-size-touch-min);

  background: transparent;
  border: 0;
  cursor: pointer;
  /* Or the browser scrolls the page instead of letting the drag through. */
  touch-action: none;
}

/* The bar itself, centred in the target. There is no inset depth token, so the
   inset is composed from the edge colours and the UI stroke width rather than
   invented as a shadow value. */
.gs-slider__track::before {
  content: '';
  position: absolute;
  inset-inline: 0;
  top: 50%;
  height: var(--gs-space-3);
  transform: translateY(-50%);
  background: var(--gs-color-muted);
  border-radius: var(--gs-radius-full);
  box-shadow:
    inset 0 var(--gs-stroke-ui) 0 var(--gs-color-edge),
    inset 0 calc(var(--gs-stroke-ui) * -1) 0 var(--gs-color-edge-high);
}

.gs-slider__track:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: var(--gs-space-1);
  border-radius: var(--gs-radius-md);
}

/* The ratio is unitless, so the travel is `(width - thumb) * ratio` and the
   thumb stays inside the bar at both ends instead of hanging half off it. */
.gs-slider__fill {
  position: absolute;
  inset-inline-start: 0;
  top: 50%;
  height: var(--gs-space-3);
  width: calc(
    var(--gs-size-icon-control) / 2 +
    (100% - var(--gs-size-icon-control)) * var(--gs-slider-ratio, 0)
  );
  transform: translateY(-50%);
  background: var(--gs-color-interactive);
  border-radius: var(--gs-radius-full);
  transition: width var(--gs-motion-press) ease-out;
}

/* -- the thumb: raised, because it is a control (BDS-040) ------------------ */
.gs-slider__thumb {
  position: absolute;
  top: 50%;
  inset-inline-start: calc((100% - var(--gs-size-icon-control)) * var(--gs-slider-ratio, 0));
  width: var(--gs-size-icon-control);
  height: var(--gs-size-icon-control);
  transform: translateY(-50%);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-control, var(--gs-stroke-ui)) solid var(--gs-color-edge-high);
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-raised);
  transition: inset-inline-start var(--gs-motion-press) ease-out,
              box-shadow var(--gs-motion-press) ease-out;
}

/* Pressable things move, they never fade (BDS-013). The thumb has the depth it
   has, so it travels that far and lands flat. */
.gs-slider__track:active:not([aria-disabled='true']) .gs-slider__thumb {
  box-shadow: var(--gs-depth-flat);
}

/* -- selected and committed ----------------------------------------------- */
/* Moved but not answered. The fill takes the selected colour and the thumb
   takes the selected stroke, so the state is two things rather than one. */
.gs-slider[data-gs-selected='true'] .gs-slider__fill {
  background: var(--gs-color-selected);
}

.gs-slider[data-gs-selected='true'] .gs-slider__thumb {
  border-width: var(--gs-stroke-selected);
  border-color: var(--gs-color-selected);
}

/* Answered. Colour, weight and a solid thumb at once, and the accessible name
   carries the word, so no player is told by colour alone. */
.gs-slider[data-gs-committed='true'] .gs-slider__fill {
  background: var(--gs-color-positive);
}

.gs-slider[data-gs-committed='true'] .gs-slider__thumb {
  background: var(--gs-color-positive);
  border-color: var(--gs-color-positive-base);
}

.gs-slider[data-gs-committed='true'] .gs-slider__value {
  color: var(--gs-color-positive);
  font-weight: 900;
}

.gs-slider[data-gs-committed='true'] .gs-slider__track { cursor: default; }

/* -- locked and disabled -------------------------------------------------- */
/* Locked keeps its shape and shows a padlock: available later, not now. */
.gs-slider[data-gs-locked='true'] .gs-slider__track { cursor: not-allowed; }

.gs-slider__glyph {
  grid-area: glyph;
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* Only disabled goes flat: not available at all. */
.gs-slider[data-gs-disabled='true'] .gs-slider__value,
.gs-slider[data-gs-disabled='true'] .gs-slider__label {
  color: var(--gs-color-disabled-ink);
}

.gs-slider[data-gs-disabled='true'] .gs-slider__fill {
  background: var(--gs-color-disabled);
}

.gs-slider[data-gs-disabled='true'] .gs-slider__thumb {
  background: var(--gs-color-disabled);
  border-color: var(--gs-color-disabled);
  box-shadow: var(--gs-depth-flat);
}

.gs-slider[data-gs-disabled='true'] .gs-slider__track { cursor: not-allowed; }

/* -- the commit control --------------------------------------------------- */
/* Its own control rather than an imported Button, so the item depends on the
   tokens and nothing else. It presses the way BDS-013 says every control does:
   the offset base collapses and the face travels the same 6px. */
.gs-slider__commit {
  grid-area: commit;
  justify-self: start;

  min-height: var(--gs-size-action);
  min-width: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-6);

  /* A theme's type.action may set a case, and one that is read in four of the
     six places the action type is used is a theme half applied. */

  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: 0;
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-pressable);
  cursor: pointer;

  transition: transform var(--gs-motion-press) ease-out,
              box-shadow var(--gs-motion-press) ease-out;
}

.gs-slider__commit:hover { background: var(--gs-color-interactive-hover); }

.gs-slider__commit:active {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-pressable-pressed);
}

.gs-slider__commit:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}
